python3 -c "
import re
a=open('input.md',encoding='utf-8').read()
for p in ['.h03-scratch/cand-a.md','.h03-scratch/cand-b.md']:
    b=open(p,encoding='utf-8').read()
    sa,sb=re.sub(r'\s+','',a),re.sub(r'\s+','',b)
    print(p,'identical_ignoring_whitespace=',sa==sb)
    if sa!=sb:
        import difflib
        for i,s in enumerate(difflib.ndiff(sa,sb)):
            if s[0]!=' ': print('  ',repr(s))
"
